export const BuyerDashboard: React.FC = () => {
  const { products, vendors, favorites, toggleFavorite, currentUser, addToCart, removeFromCart, cart, isDataLoading } = useApp();
  const navigate = useNavigate();
  const [selectedCat, setSelectedCat] = useState('All');
  const [sortType, setSortType] = useState<'nearby' | 'price' | 'rating'>('nearby');
  const [userLocation, setUserLocation] = useState<{lat: number, lng: number} | null>(null);

  useEffect(() => {
      if (navigator.geolocation) {
          navigator.geolocation.getCurrentPosition(
              (position) => setUserLocation({ lat: position.coords.latitude, lng: position.coords.longitude }),
              () => setUserLocation({ lat: 5.6506, lng: -0.1962 })
          );
      }
  }, []);

  const getDistanceFromLatLonInKm = (lat1: number, lon1: number, lat2: number, lon2: number) => {
      const R = 6371; 
      const dLat = (lat2 - lat1) * (Math.PI/180);
      const dLon = (lon2 - lon1) * (Math.PI/180);
      const a = Math.sin(dLat/2) * Math.sin(dLat/2) + Math.cos(lat1 * (Math.PI/180)) * Math.cos(lat2 * (Math.PI/180)) * Math.sin(dLon/2) * Math.sin(dLon/2); 
      return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a))); 
  };

  const getCoordsForLocation = (locStr: string): {lat: number, lng: number} | null => {
      const clean = locStr.toLowerCase();
      if (INITIAL_LOCATION_CACHE[clean]) return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
      const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
      if (key) return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
      return null;
  };

  const handleStartSelling = () => {
    if (!currentUser) {
        navigate('/register', { state: { role: 'vendor' } });
    } else if (currentUser.roles.includes('vendor')) {
        navigate('/vendor/dashboard');
    } else {
        navigate('/vendor/onboarding');
    }
  };

  const categoryList = useMemo(() => [
      { id: 'cat-all', name: 'All', icon: 'layer-group', image: '' },
      ...CATEGORIES
  ], []);

  const trendingItems = useMemo(() => {
      return products.filter(p => p.isTrending && p.status === 'approved');
  }, [products]);

  const sortedProducts = useMemo(() => {
      const approvedProducts = products.filter(p => p.status === 'approved');
      let filtered = selectedCat === 'All' ? approvedProducts : approvedProducts.filter(p => p.category === selectedCat);

      if (sortType === 'price') return [...filtered].sort((a, b) => a.price - b.price);
      if (sortType === 'rating') return [...filtered].sort((a, b) => (b.rating || 0) - (a.rating || 0));
      if (sortType === 'nearby' && userLocation) {
          return [...filtered].sort((a, b) => {
              const coordsA = getCoordsForLocation(a.location);
              const coordsB = getCoordsForLocation(b.location);
              const distA = coordsA ? getDistanceFromLatLonInKm(userLocation.lat, userLocation.lng, coordsA.lat, coordsA.lng) : 999;
              const distB = coordsB ? getDistanceFromLatLonInKm(userLocation.lat, userLocation.lng, coordsB.lat, coordsB.lng) : 999;
              return distA - distB;
          });
      }
      return filtered;
  }, [products, selectedCat, sortType, userLocation]);

  return (
    <div className="flex flex-col space-y-6 animate-fade-in pb-4 bg-transparent min-h-screen overflow-x-hidden">
      <div className="bg-white/40 dark:bg-darkSurface/60 backdrop-blur-xl pt-2 pb-3 px-4 sticky top-0 z-30 border-b border-white/50 dark:border-white/5 shadow-sm space-y-3 transition-colors duration-500">
        <div className="relative group" onClick={() => navigate('/buyer/search')}>
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <i className="fa-solid fa-magnifying-glass text-gray-400"></i>
            </div>
            <input readOnly placeholder="Search Products..." className="block w-full rounded-xl border border-white/60 dark:border-gray-700 bg-white/50 dark:bg-darkBg py-3 pl-10 pr-4 text-sm text-gray-900 dark:text-white cursor-pointer hover:bg-white dark:hover:bg-darkSurface transition-all" />
        </div>

        <div className="flex gap-2 overflow-x-auto hide-scrollbar pb-1">
            {['nearby', 'price', 'rating'].map(type => (
                <button 
                    key={type} 
                    onClick={() => setSortType(type as any)} 
                    className={`px-4 py-2 rounded-full text-xs font-bold capitalize whitespace-nowrap transition-all border ${sortType === type ? 'bg-primary text-white border-primary shadow-glow' : 'bg-white/60 dark:bg-darkSurface text-gray-500 border-white/50 dark:border-gray-800'}`}
                >
                    {type === 'nearby' ? 'Nearby' : type === 'price' ? 'Low Price' : 'Top Rated'}
                </button>
            ))}
        </div>
      </div>

      {/* Standalone Install Banner Component */}
      <InstallBanner />

      <div className="pl-4">
        <h3 className="font-display font-black text-gray-900 dark:text-white text-lg mb-4 uppercase tracking-tight">Categories</h3>
        <div className="flex gap-4 overflow-x-auto hide-scrollbar pb-2 pr-4">
            {categoryList.map(cat => (
                <div key={cat.id} className="flex flex-col items-center gap-2 cursor-pointer min-w-[80px] group" onClick={() => setSelectedCat(cat.name)}>
                    <div className={`w-16 h-16 rounded-full flex items-center justify-center transition-all overflow-hidden border-2 ${selectedCat === cat.name ? 'border-primary ring-4 ring-primary/10 scale-105 shadow-lg' : 'border-transparent bg-white/60 dark:bg-darkSurface text-gray-500 shadow-sm group-hover:scale-105'}`}>
                        {cat.image ? <img src={cat.image} className="w-full h-full object-cover" /> : <i className={`fa-solid fa-${cat.icon} text-xl`}></i>}
                    </div>
                    <span className={`text-[11px] font-black uppercase transition-colors ${selectedCat === cat.name ? 'text-primary' : 'text-gray-500'}`}>{cat.name}</span>
                </div>
            ))}
        </div>
      </div>

      <div className="px-4">
        <div className="relative overflow-hidden rounded-[2.5rem] bg-gradient-to-br from-slate-900 via-purple-950 to-slate-900 p-8 shadow-2xl group transition-all duration-500 hover:shadow-primary/20 dark:via-darkSurface dark:to-darkBg dark:border dark:border-white/5">
            <div className="absolute top-0 right-0 w-64 h-64 bg-primary/20 rounded-full blur-3xl -mr-20 -mt-20 opacity-50 group-hover:scale-125 transition-transform duration-700 dark:hidden"></div>
            <div className="flex justify-between items-center relative z-10">
                <div className="max-w-[65%] space-y-4">
                    <div className="space-y-1">
                        <h2 className="text-3xl font-display font-black text-white leading-tight">Student Entrepreneur?</h2>
                        <p className="text-purple-200/80 text-sm font-medium leading-relaxed dark:text-gray-400">Reach thousands of students on campus today.</p>
                    </div>
                    <button onClick={handleStartSelling} className="bg-primary hover:bg-primaryDark text-white px-8 py-3 rounded-2xl font-black text-sm transition-all transform active:scale-95 shadow-lg shadow-primary/20">Start Selling</button>
                </div>
                <div className="relative">
                    <div className="w-24 h-24 sm:w-32 sm:h-32 bg-white/5 backdrop-blur-md rounded-[2.5rem] border border-white/10 flex items-center justify-center rotate-6 group-hover:rotate-12 transition-transform duration-500 shadow-2xl">
                        <i className="fa-solid fa-store text-4xl sm:text-5xl text-white/90"></i>
                    </div>
                </div>
            </div>
        </div>
      </div>

      {trendingItems.length > 0 && (
          <div className="space-y-4">
              <div className="flex items-center gap-2 px-4">
                  <h3 className="font-display font-black text-gray-900 dark:text-white text-lg uppercase tracking-tight">Trending Now</h3>
              </div>
              <div className="relative w-full overflow-hidden">
                  <div className="flex animate-scroll hover:pause-on-hover py-0.5 w-max gap-4 px-4">
                      {[...trendingItems, ...trendingItems, ...trendingItems].map((p, idx) => (
                          <div key={`${p.id}-${idx}`} onClick={() => navigate(`/buyer/product/${p.id}`)} className="w-40 flex-shrink-0 bg-white/60 dark:bg-darkSurface/60 backdrop-blur-xl rounded-2xl shadow-sm border border-white/50 dark:border-gray-800/50 overflow-hidden cursor-pointer group hover:-translate-y-1 transition-all duration-300">
                              <div className="h-32 overflow-hidden relative bg-gray-50 dark:bg-gray-900">
                                  <img src={p.images[0]} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" alt="" />
                                  <div className="absolute top-2 left-2">
                                      <div className="bg-primary/90 text-white text-[8px] font-black px-2 py-1 rounded-md uppercase tracking-tighter shadow-sm backdrop-blur-sm">Featured</div>
                                  </div>
                              </div>
                              <div className="p-3">
                                  <p className="text-[10px] font-bold text-gray-900 dark:text-white truncate mb-1 font-display uppercase">{p.title}</p>
                                  <div className="flex justify-between items-center">
                                      <p className="text-primary font-black text-xs">₵{p.price.toFixed(0)}</p>
                                      <i className="fa-solid fa-chevron-right text-[8px] text-gray-300 group-hover:text-primary transition-colors"></i>
                                  </div>
                              </div>
                          </div>
                      ))}
                  </div>
              </div>
          </div>
      )}

      <div className="px-4 pb-24">
         <div className="flex justify-between items-center mb-6">
            <h3 className="font-display font-black text-gray-900 dark:text-white text-lg uppercase tracking-tight">Discover Campus</h3>
         </div>

         {isDataLoading ? (
             <div className="grid grid-cols-2 gap-4">
                 {[...Array(6)].map((_, i) => <ProductCardSkeleton key={i} />)}
             </div>
         ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                {sortedProducts.map(product => {
                    const vendor = vendors.find(v => v.vendorId === product.vendorId);
                    const isInCart = cart.some(item => item.productId === product.id);
                    const isFavorite = favorites.includes(product.id);
                    return (
                        <div key={product.id} className="bg-white/60 dark:bg-darkSurface/60 backdrop-blur-xl rounded-[2rem] overflow-hidden shadow-sm border border-white/50 dark:border-gray-800 flex flex-col h-full cursor-pointer relative group transition-all hover:shadow-lg" onClick={() => navigate(`/buyer/product/${product.id}`)}>
                            <div className="aspect-square relative overflow-hidden bg-gray-50/50 dark:bg-darkBg/90">
                                <img src={product.images[0]} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" alt={product.title} />
                                <button onClick={(e) => { e.stopPropagation(); toggleFavorite(product.id); }} className={`absolute top-3 right-3 w-9 h-9 rounded-full flex items-center justify-center transition-all duration-300 transform ${isFavorite ? 'bg-red-500 text-white shadow-lg' : 'bg-white/80 dark:bg-darkSurface/80 text-gray-400 hover:text-red-500 group-hover:scale-100 group-hover:opacity-100 opacity-0 scale-90'}`}>
                                    <i className={`fa-${isFavorite ? 'solid' : 'regular'} fa-heart text-[12px]`}></i>
                                </button>
                            </div>
                            <div className="p-4 flex flex-col justify-between flex-grow">
                                <div>
                                    <h3 className="text-sm text-gray-900 dark:text-white font-bold leading-tight line-clamp-2">{product.title}</h3>
                                    <p className="text-[11px] text-gray-400 mt-1.5 font-bold uppercase tracking-tight">{vendor?.storeName}</p>
                                </div>
                                <div className="flex items-center justify-between mt-4">
                                    <span className="text-base font-black text-gray-900 dark:text-white">₵{product.price}</span>
                                    <button className={`w-9 h-9 rounded-2xl flex items-center justify-center text-white transition-all shadow-sm ${isInCart ? 'bg-green-500' : 'bg-primary active:scale-90 hover:shadow-lg'}`} onClick={(e) => { e.stopPropagation(); if (product.stock > 0) isInCart ? removeFromCart(product.id) : addToCart(product); }}>
                                        <i className={`fa-solid ${isInCart ? 'fa-check' : 'fa-plus'} text-[12px]`}></i>
                                    </button>
                                </div>
                            </div>
                        </div>
                    )
                })}
            </div>
         )}
      </div>
    </div>
  );
};

import React, { createContext, useContext, useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { User, Product, Vendor, Order, CartItem, Courier, Role, OrderStatus, ToastMessage, Notification, Review } from './types';
import { supabase } from './supabaseClient';
import { INITIAL_LOCATION_CACHE, UPSA_LOCATION_CACHE } from './constants';

type ThemeMode = 'light' | 'dark' | 'system';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  couriers: Courier[];
  users: User[];
  notifications: Notification[];
  reviews: Review[];
  unreadCount: number;
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;
  theme: ThemeMode;
  isThemeSwitchingAllowed: boolean;
  deferredPrompt: any;
  isInstallable: boolean;
  isIOS: boolean;
  isStandalone: boolean;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string, user?: any, role?: Role}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;
  updateTheme: (theme: ThemeMode) => void;
  toggleThemeSwitching: (allowed: boolean) => void;
  installApp: () => Promise<void>;

  updateProfile: (data: Partial<User>) => Promise<{ success: boolean }>;
  submitContactMessage: (name: string, email: string, message: string) => Promise<{ success: boolean }>;
  requestPayout: (amount: number, method: string) => Promise<{ success: boolean }>;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerCourier: (data: Partial<Courier> & { phoneNumber?: string }, explicitUserId?: string) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string, campus?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  toggleTrendingStatus: (id: string, isTrending: boolean) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  markNotificationRead: (id: string) => Promise<void>;
  markAllNotificationsRead: () => Promise<void>;
  deleteNotification: (id: string) => Promise<void>;
  sendNotification: (payload: Partial<Notification>) => Promise<boolean>;

  submitReview: (review: Omit<Review, 'createdAt' | 'user'>) => Promise<boolean>;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveCourier: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (UPSA_LOCATION_CACHE[clean]) return { lat: UPSA_LOCATION_CACHE[clean][0], lng: UPSA_LOCATION_CACHE[clean][1] };
    if (INITIAL_LOCATION_CACHE[clean]) return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    return { lat: 5.6506, lng: -0.1962 }; 
};

const mapProduct = (p: any): Product => ({ 
    ...p, 
    vendorId: p.vendor_id, 
    contactPhone: p.contact_phone, 
    isTrending: p.is_trending 
});

const mapOrder = (o: any): Order => ({ 
    ...o, 
    vendorId: o.vendor_id, 
    buyerId: o.buyer_id, 
    courierId: o.courier_id, 
    deliveryFee: o.delivery_fee, 
    deliveryOption: o.delivery_option, 
    createdAt: o.created_at, 
    items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items, 
    locationCoordinates: o.location_coordinates, 
    pickupCoordinates: o.pickup_coordinates 
});

const mapNotification = (n: any): Notification => ({
    ...n, 
    userId: n.user_id, 
    targetRole: n.target_role,
    targetScope: n.target_scope, 
    relatedId: n.related_id,
    isRead: n.is_read, 
    createdAt: n.created_at
});

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(false);
  const [connectionError, setConnectionError] = useState<boolean>(false);

  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [couriers, setCouriers] = useState<Courier[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [reviews, setReviews] = useState<Review[]>([]);
  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  const [theme, setTheme] = useState<ThemeMode>(() => {
      try { return (localStorage.getItem('lynqed_theme_last') as ThemeMode) || 'system'; } catch { return 'system'; }
  });
  const [isThemeSwitchingAllowed, setIsThemeSwitchingAllowed] = useState<boolean>(() => {
      try { return localStorage.getItem('lynqed_sys_theme_allowed') !== 'false'; } catch { return true; }
  });
  const [toast, setToast] = useState<ToastMessage | null>(null);

  // PWA State
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isInstallable, setIsInstallable] = useState<boolean>(false);
  const [isIOS, setIsIOS] = useState<boolean>(false);
  const [isStandalone, setIsStandalone] = useState<boolean>(false);

  const hasInitializedData = useRef(false);

  const showToast = useCallback((message: string, type: 'success' | 'error' | 'info') => {
      setToast({ id: Date.now(), message, type });
  }, []);

  const hideToast = useCallback(() => setToast(null), []);

  useEffect(() => {
    const root = window.document.documentElement;
    const isDark = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
    if (!isThemeSwitchingAllowed) {
        root.classList.remove('dark');
    } else {
        if (isDark) root.classList.add('dark');
        else root.classList.remove('dark');
    }
  }, [theme, isThemeSwitchingAllowed]);

  // Enhanced PWA Logic
  useEffect(() => {
    const handler = (e: any) => {
        e.preventDefault();
        setDeferredPrompt(e);
        setIsInstallable(true);
    };
    window.addEventListener('beforeinstallprompt', handler);
    const ios = /iPad|iPhone|iPod/.test(navigator.userAgent) && !(window as any).MSStream;
    setIsIOS(ios);
    const standalone = window.matchMedia('(display-mode: standalone)').matches || (navigator as any).standalone === true;
    setIsStandalone(standalone);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  const installApp = async () => {
      if (deferredPrompt) {
          deferredPrompt.prompt();
          const { outcome } = await deferredPrompt.userChoice;
          if (outcome === 'accepted') {
              setIsInstallable(false);
              setDeferredPrompt(null);
          }
      } else if (isIOS) {
          showToast("Tap 'Share' and then 'Add to Home Screen'", "info");
      } else {
          showToast("Open this in your mobile browser to install.", "info");
      }
  };

  const fetchEssentialData = useCallback(async () => {
    const [pData, vData] = await Promise.all([
      supabase.from('products').select('*').order('created_at', { ascending: false }),
      supabase.from('vendors').select('*')
    ]);
    if (pData.data) setProducts(pData.data.map(mapProduct));
    if (vData.data) {
        setVendors(vData.data.map((v: any) => ({ 
            ...v, 
            userId: v.user_id, // Map database snake_case to app camelCase
            vendorId: v.vendor_id, 
            storeName: v.store_name, 
            storeDescription: v.store_description, 
            location: v.location, 
            contactPhone: v.contact_phone, 
            storeAvatarUrl: v.store_avatar_url, 
            isApproved: v.is_approved, 
            rating: v.rating, 
            campus: v.campus 
        })));
    }
  }, []);

  const fetchHeavyData = useCallback(async (role: Role) => {
    if (role === 'guest') return;
    const requests: Promise<any>[] = [
      supabase.from('orders').select('*').order('created_at', { ascending: false })
    ];
    if (role === 'admin' || role === 'courier') requests.push(supabase.from('couriers').select('*'));
    if (role === 'admin') requests.push(supabase.from('profiles').select('*'));
    const results = await Promise.all(requests);
    if (results[0]?.data) setOrders(results[0].data.map(mapOrder));
    if (role === 'admin' || role === 'courier') {
       const courierData = results.find(r => r?.data && (r.data.length === 0 || 'vehicle_type' in r.data[0]));
       if (courierData?.data) setCouriers(courierData.data.map((d: any) => ({ ...d, userId: d.user_id, vehicleType: d.vehicle_type, onlineStatus: d.online_status, status: d.status, verified: d.status === 'approved', payoutMethod: d.payout_method })));
    }
    if (role === 'admin') {
       const profileData = results.find(r => r?.data && r.data.length > 0 && 'roles' in r.data[0]);
       if (profileData?.data) setUsers(profileData.data as any);
    }
  }, []);

  const fetchReviews = useCallback(async () => {
    const { data } = await supabase.from('reviews').select('*, profiles(name, avatar_url)').order('created_at', { ascending: false });
    if (data) {
        setReviews(data.map(r => ({
            ...r, productId: r.product_id, vendorId: r.vendor_id,
            userId: r.user_id, createdAt: r.created_at,
            user: { name: r.profiles?.name || 'User', avatarUrl: r.profiles?.avatar_url || '' }
        })));
    }
  }, []);

  const fetchNotifications = useCallback(async (userId: string, role: Role) => {
    if (!userId) return;
    const { data } = await supabase
      .from('notifications')
      .select('*')
      .or(`user_id.eq.${userId},target_scope.eq.global,target_scope.eq.role`)
      .order('created_at', { ascending: false });

    if (data) {
        const filtered = data.filter(n => n.target_scope !== 'role' || n.target_role === role);
        setNotifications(filtered.map(mapNotification));
    }
  }, []);

  const initialize = useCallback(async () => {
    if (hasInitializedData.current) return;
    setIsLoading(true);
    const { data: { session } } = await supabase.auth.getSession();

    // FETCH VENDORS FIRST TO ENSURE NO RACE CONDITION ON DASHBOARDS
    await fetchEssentialData(); 

    if (session?.user) {
        const { data: profile } = await supabase.from('profiles').select('*').eq('id', session.user.id).maybeSingle();
        if (profile) {
            const user: User = { ...profile, roles: profile.roles || ['buyer'], avatarUrl: profile.avatar_url, phoneNumber: profile.phone_number, defaultLocation: profile.address };
            setCurrentUser(user);
            const persistedRole = localStorage.getItem('lynqed_role') as Role;
            const finalRole: Role = (persistedRole && user.roles.includes(persistedRole)) ? persistedRole : (user.roles.includes('admin') ? 'admin' : (user.roles.includes('vendor') ? 'vendor' : 'buyer'));
            setCurrentRole(finalRole);
            await Promise.all([fetchNotifications(session.user.id, finalRole), fetchHeavyData(finalRole)]);
        }
    }
    await fetchReviews();
    setIsLoading(false);
    hasInitializedData.current = true;
  }, [fetchEssentialData, fetchHeavyData, fetchNotifications, fetchReviews]);

  useEffect(() => {
    initialize();
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_IN' && session?.user) {
            if (!hasInitializedData.current || (currentUser && currentUser.id !== session.user.id)) {
                hasInitializedData.current = false; 
                initialize();
            }
        } else if (event === 'SIGNED_OUT') {
            setCurrentUser(null); setCurrentRole('guest'); setNotifications([]); hasInitializedData.current = false;
        }
    });
    return () => { subscription.unsubscribe(); };
  }, [initialize, currentUser]);

  useEffect(() => {
    if (isLoading) return;
    const channel = supabase.channel('schema-db-changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, (payload) => {
          if (payload.eventType === 'INSERT') setProducts(prev => [mapProduct(payload.new), ...prev]);
          if (payload.eventType === 'UPDATE') setProducts(prev => prev.map(p => p.id === payload.new.id ? mapProduct(payload.new) : p));
          if (payload.eventType === 'DELETE') setProducts(prev => prev.filter(p => p.id !== payload.old.id));
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
          if (payload.eventType === 'INSERT') setOrders(prev => [mapOrder(payload.new), ...prev]);
          if (payload.eventType === 'UPDATE') setOrders(prev => prev.map(o => o.id === payload.new.id ? mapOrder(payload.new) : o));
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'notifications' }, (payload) => {
          if (payload.eventType === 'INSERT') {
              const mapped = mapNotification(payload.new);
              if (mapped.targetScope === 'global' || (mapped.targetScope === 'role' && mapped.targetRole === currentRole) || (mapped.userId === currentUser?.id)) setNotifications(prev => [mapped, ...prev]);
          }
          if (payload.eventType === 'UPDATE') setNotifications(prev => prev.map(n => n.id === payload.new.id ? mapNotification(payload.new) : n));
          if (payload.eventType === 'DELETE') setNotifications(prev => prev.filter(n => n.id !== payload.old.id));
      })
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [isLoading, currentRole, currentUser?.id]);

  const login = async (email: string, pass: string): Promise<{success: boolean, role?: Role, error?: string}> => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) return { success: false, error: error.message };
      const { data: profile } = await supabase.from('profiles').select('*').eq('id', data.user.id).maybeSingle();
      const roles = profile?.roles || ['buyer'];
      const primaryRole: Role = roles.includes('admin') ? 'admin' : (roles.includes('vendor') ? 'vendor' : (roles.includes('courier') ? 'courier' : 'buyer'));
      const user: User = { ...profile, roles: roles, avatarUrl: profile?.avatar_url, phoneNumber: profile?.phone_number, defaultLocation: profile?.address };
      setCurrentUser(user);
      setCurrentRole(primaryRole);
      localStorage.setItem('lynqed_role', primaryRole);
      hasInitializedData.current = true;
      setIsDataLoading(true);
      await Promise.all([fetchEssentialData(), fetchNotifications(data.user.id, primaryRole), fetchHeavyData(primaryRole)]);
      setIsDataLoading(false);
      return { success: true, role: primaryRole };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string): Promise<{success: boolean, error?: string, user?: any, role?: Role}> => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           const roles: Role[] = role === 'buyer' ? ['buyer'] : ['buyer', role];
           const profileObj = { id: data.user.id, email, name: fullName, roles: roles, phone_number: phoneNumber };
           await supabase.from('profiles').insert(profileObj);
           const user: User = { id: data.user.id, email, name: fullName, roles: roles, phoneNumber: phoneNumber };
           setCurrentUser(user); setCurrentRole(role); localStorage.setItem('lynqed_role', role);
           hasInitializedData.current = true;
           return { success: true, user: data.user, role }; 
      }
      return { success: false };
  };

  const logout = async () => { await supabase.auth.signOut(); hasInitializedData.current = false; setCurrentUser(null); setCurrentRole('guest'); setNotifications([]); };

  const switchRoleLocal = (role: Role) => { if(currentUser?.roles.includes(role)) { setCurrentRole(role); localStorage.setItem('lynqed_role', role); showToast(`Mode: ${role}`, 'info'); fetchHeavyData(role); } };

  const updateProfile = async (data: Partial<User>) => { 
      if(!currentUser) return { success: false }; 
      const { error } = await supabase.from('profiles').update({ name: data.name, avatar_url: data.avatarUrl, phone_number: data.phoneNumber, address: data.address }).eq('id', currentUser.id); 
      if(!error) { setCurrentUser(prev => prev ? ({ ...prev, ...data }) : null); return { success: true }; } 
      return { success: false }; 
  };

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileName = `${Math.random().toString(36).substring(2)}_${Date.now()}.${file.name.split('.').pop()}`;
          const { error: upErr } = await supabase.storage.from('lynqed-assets').upload(`${folder}/${fileName}`, file);
          if (upErr) throw upErr;
          return supabase.storage.from('lynqed-assets').getPublicUrl(`${folder}/${fileName}`).data.publicUrl;
      } catch (e) { return null; }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      const ex = vendors.find(v => v.userId === currentUser.id);
      const vid = ex?.vendorId || `v-${Date.now()}`;

      const { error } = await supabase.from('vendors').upsert({ 
          vendor_id: vid, 
          user_id: currentUser.id, 
          store_name: data.storeName, 
          store_description: data.storeDescription, 
          location: data.location, 
          contact_phone: data.contactPhone, 
          store_avatar_url: data.storeAvatarUrl, 
          is_approved: ex ? ex.isApproved : false, 
          rating: ex ? ex.rating : 5.0, 
          campus: data.campus 
      }, { onConflict: 'user_id' });

      if (!error) { 
          if (!currentUser.roles.includes('vendor')) {
              const newRoles = [...new Set([...currentUser.roles, 'vendor' as Role, 'buyer' as Role])];
              await supabase.from('profiles').update({ roles: newRoles }).eq('id', currentUser.id); 
              setCurrentUser(prev => prev ? ({ ...prev, roles: newRoles }) : null);
          }
          await fetchEssentialData(); 
          return { success: true }; 
      }
      return { success: false };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) return false;
      const v = vendors.find(v => v.userId === currentUser.id);
      if(!v) return false;
      const { data, error } = await supabase.from('products').insert({ vendor_id: v.vendorId, title: prod.title, description: prod.description, price: prod.price, category: prod.category, images: prod.images, stock: prod.stock, status: 'pending', location: prod.location, campus: v.campus, contact_phone: prod.contact_phone }).select().single();
      if (!error && data) { setProducts(prev => [mapProduct(data), ...prev]); showToast("Listing Published Successfully", "success"); return true; }
      return false;
  };

  const updateProduct = async (id: string, data: any) => { 
      const { data: updated, error } = await supabase.from('products').update({ ...data, contact_phone: data.contactPhone }).eq('id', id).select().single(); 
      if (!error && updated) { setProducts(prev => prev.map(p => p.id === id ? mapProduct(updated) : p)); showToast("Listing Updated", "success"); }
  };

  const deleteProduct = async (id: string) => { 
      const { error } = await supabase.from('products').delete().eq('id', id); 
      if (!error) setProducts(prev => prev.filter(p => p.id !== id));
  };

  const updateProductStatus = async (id: string, status: string) => { 
      const { data, error } = await supabase.from('products').update({status}).eq('id', id).select().single(); 
      if (!error && data) setProducts(prev => prev.map(p => p.id === id ? mapProduct(data) : p));
  };

  const toggleTrendingStatus = async (id: string, isTrending: boolean) => { 
      const { data, error } = await supabase.from('products').update({ is_trending: isTrending }).eq('id', id).select().single(); 
      if (!error && data) setProducts(prev => prev.map(p => p.id === id ? mapProduct(data) : p));
  };

  const addToCart = useCallback((p: Product, q = 1) => { setCart(prev => { const x = prev.find(i => i.productId === p.id); return x ? prev.map(i => i.productId === p.id ? { ...i, quantity: i.quantity + q } : i) : [...prev, { productId: p.id, quantity: q, product: p }]; }); showToast(`Added ${p.title}`, "success"); }, [showToast]);
  const removeFromCart = useCallback((pid: string) => { setCart(prev => prev.filter(i => i.productId !== pid)); showToast("Removed", "info"); }, [showToast]);
  const updateCartQuantity = useCallback((pid: string, qty: number) => { if(qty <= 0) removeFromCart(pid); else { setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i)); } }, [removeFromCart]);
  const clearCart = useCallback(() => { setCart([]); }, []);

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });
      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);
              const { data, error } = await supabase.from('orders').insert({ buyer_id: currentUser.id, vendor_id: vid, items, total: subtotal+fee, delivery_fee: fee, status: 'placed', delivery_option: option, pickup_coordinates: vendor ? resolveCoordinates(vendor.location) : undefined, location_coordinates: resolveCoordinates(currentUser.address || 'campus') }).select().single();
              if (vendor) await sendNotification({ userId: vendor.userId, type: 'new_order', title: 'New Order!', message: `₵${(subtotal+fee).toFixed(2)} order received from ${currentUser.name}.`, relatedId: data.id, priority: 'high' });
              if (!error && data) setOrders(prev => [mapOrder(data), ...prev]);
          }
          showToast("Order Placed!", "success"); clearCart();
      } catch (e) { showToast("Order failed", "error"); }
  };

  const updateOrderStatus = async (orderId: string, status: string) => { 
      const { data, error } = await supabase.from('orders').update({status}).eq('id', orderId).select().single(); 
      if (!error && data) { 
          setOrders(prev => prev.map(o => o.id === orderId ? mapOrder(data) : o));
          const order = orders.find(o => o.id === orderId);
          if (order) {
              await sendNotification({ userId: order.buyerId, type: 'order_update', title: 'Order Update', message: `Order #${orderId.slice(-4)}: Status changed to ${status.replace('_', ' ')}.`, relatedId: orderId }); 
              if (status === 'ready_for_pickup' && order.deliveryOption === 'delivery') {
                  await sendNotification({ targetRole: 'courier', targetScope: 'role', type: 'delivery', title: 'New Delivery Available!', message: `A new order is ready for delivery at ${order.vendorId.slice(-4)}. Claim it now!`, relatedId: orderId, priority: 'high' });
              }
          }
      } 
  };

  const approveVendor = async (vid: string, s: boolean) => { const { error } = await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid); if (!error) fetchEssentialData(); };
  const approveCourier = async (id: string, userId: string, status: string) => { await supabase.from('couriers').update({status}).eq('id', id); fetchHeavyData(currentRole); };
  const toggleDriverStatus = async (isOn: boolean) => { if(!currentUser) return; const c = couriers.find(d => d.userId === currentUser.id); if(c) { await supabase.from('couriers').update({ online_status: isOn }).eq('id', c.id); fetchHeavyData(currentRole); } };
  const updateDriverLocation = async (lat: number, lng: number) => { if(!currentUser) return; const c = couriers.find(d => d.userId === currentUser.id); if(c) supabase.from('couriers').update({ current_lat: lat, current_lng: lng }).eq('id', c.id).then(); };
  const assignDelivery = async (oid: string) => { if (!currentUser) return; await supabase.from('orders').update({ courier_id: currentUser.id, status: 'courier_assigned' }).eq('id', oid); fetchHeavyData(currentRole); };

  const updateTheme = (t: ThemeMode) => { setTheme(t); localStorage.setItem('lynqed_theme_last', t); };
  const toggleThemeSwitching = (allowed: boolean) => { setIsThemeSwitchingAllowed(allowed); localStorage.setItem('lynqed_sys_theme_allowed', String(allowed)); };
  const resetPassword = async (email: string) => { const { error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}/#/update-password` }); return { success: !error, error: error?.message }; };
  const updatePassword = async (newPassword: string) => { const { error } = await supabase.auth.updateUser({ password: newPassword }); return { success: !error, error: error?.message }; };
  const toggleFavorite = useCallback((pid: string) => { const isRem = favorites.includes(pid); setFavorites(prev => isRem ? prev.filter(i => i !== pid) : [...prev, pid]); showToast(isRem ? 'Removed' : 'Saved', isRem ? 'info' : 'success'); }, [favorites, showToast]);

  const markNotificationRead = async (id: string) => { setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: true } : n)); const { error } = await supabase.from('notifications').update({ is_read: true }).eq('id', id); if (error) setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: false } : n)); };
  const markAllNotificationsRead = async () => { if (!currentUser) return; const oldState = [...notifications]; const visibleIds = notifications.filter(n => !n.isRead).map(n => n.id); if (visibleIds.length === 0) return; setNotifications(prev => prev.map(n => ({ ...n, isRead: true }))); const { error } = await supabase.from('notifications').update({ is_read: true }).in('id', visibleIds); if (error) setNotifications(oldState); };
  const deleteNotification = async (id: string) => { setNotifications(prev => prev.filter(n => n.id !== id)); await supabase.from('notifications').delete().eq('id', id); };
  const sendNotification = useCallback(async (payload: Partial<Notification>) => { const { error } = await supabase.from('notifications').insert({ user_id: payload.userId || null, target_role: payload.targetRole || null, target_scope: payload.targetScope || 'individual', type: payload.type || 'system', title: payload.title || 'Notification', message: payload.message || '', related_id: payload.relatedId || null, priority: payload.priority || 'normal', is_read: false }); return !error; }, []);
  const submitReview = useCallback(async (review: Omit<Review, 'createdAt' | 'user'>) => { try { const { error } = await supabase.from('reviews').upsert({ id: review.id || undefined, product_id: review.productId, vendor_id: review.vendorId, user_id: review.userId, rating: review.rating, comment: review.comment, images: review.images }); if (error) throw error; showToast("Review submitted!", "success"); fetchReviews(); return true; } catch (e) { showToast("Failed to submit review", "error"); return false; } }, [showToast, fetchReviews]);
  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchHeavyData(currentRole); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchHeavyData(currentRole); };
  const registerCourier = async (data: any, explicitUserId?: string): Promise<{ success: boolean }> => { const uid = explicitUserId || currentUser?.id; if(!uid) return { success: false }; const { error } = await supabase.from('couriers').insert({ user_id: uid, status: 'pending', full_name: data.fullName, vehicle_type: data.vehicle_type }); fetchHeavyData(currentRole); return { success: !error }; };
  const submitContactMessage = async (name: string, email: string, message: string) => { await supabase.from('contact_messages').insert({ name, email, message }); showToast("Sent!", "success"); return { success: true }; };
  const requestPayout = async (amount: number, method: string) => { if(!currentUser) return { success: false }; await supabase.from('payout_requests').insert({ user_id: currentUser.id, amount, method, status: 'pending' }); showToast("Requested", "success"); return { success: true }; };

  const unreadCount = useMemo(() => notifications.filter(n => !n.isRead).length, [notifications]);

  const contextValue = useMemo(() => ({
    currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, unreadCount, isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed, deferredPrompt, isInstallable, isIOS, isStandalone,
    login, signup, logout, resetPassword, updatePassword, switchRole: switchRoleLocal, updateTheme, toggleThemeSwitching, installApp,
    updateProfile, submitContactMessage, requestPayout, uploadFile, registerCourier, registerVendor, refreshData: fetchEssentialData,
    addProduct, updateProduct, updateProductStatus, toggleTrendingStatus, deleteProduct, addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
    markNotificationRead, markAllNotificationsRead, deleteNotification, sendNotification, submitReview, banUser, deleteUser, approveVendor, approveCourier, toggleDriverStatus, updateDriverLocation, showToast, hideToast
  }), [currentUser, currentRole, products, vendors, orders, cart, couriers, users, notifications, reviews, unreadCount, isLoading, isDataLoading, connectionError, favorites, toast, theme, isThemeSwitchingAllowed, deferredPrompt, isInstallable, isIOS, isStandalone, addToCart, removeFromCart, updateCartQuantity, fetchEssentialData, sendNotification, submitReview, toggleFavorite]);

  return <AppContext.Provider value={contextValue}>{children}</AppContext.Provider>;
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (context === undefined) throw new Error('useApp must be used within an AppProvider');
  return context;
};

