  if (isLoading || (isDataLoading && !currentVendor)) {
      return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;
  }

  if (currentVendor && !currentVendor.isApproved) {
